#include <iostream>

void	rev_hexa(int n)
{
	while (n > 0)
	{
		int rem = n % 16;
		char digit;
		if (rem < 10)
			digit = ('0' + rem);
		else
			digit = ('A' + (rem - 10));
		std::cout << digit;
		n = n / 16;
	}
}

int	main(void)
{
	int	nbr;

	std::cin >> nbr;
	if (nbr == 0)
	{
		std::cout << '0' << '\n';
		return 0;
	}
	rev_hexa(nbr);
	std::cout << '\n';
	return 0;
}
